'use client';

import { useMemo, useState } from 'react';

const API_ERROR = 'Authentication service is unavailable. Try again shortly.';
const MAX_USERNAME_LENGTH = 64;

type AuthMode = 'register' | 'login';

function normalizeUsername(raw: string): string {
  return raw.trim();
}

function sanitizeErrorMessage(raw: string): string {
  return raw.replace(/<[^>]*>/g, '').slice(0, 200);
}

export default function LoginPage() {
  const [username, setUsername] = useState('');
  const [error, setError] = useState<string | null>(null);
  const [submitting, setSubmitting] = useState<AuthMode | null>(null);

  const isBusy = useMemo(() => submitting !== null, [submitting]);

  const submit = async (mode: AuthMode) => {
    const cleaned = normalizeUsername(username);

    if (!cleaned) {
      setError('Username is required');
      return;
    }

    if (cleaned.length > MAX_USERNAME_LENGTH) {
      setError('Username must be 64 characters or fewer');
      return;
    }

    setError(null);
    setSubmitting(mode);

    const endpoint = mode === 'register' ? '/api/auth/register-options' : '/api/auth/login-options';

    try {
      const response = await fetch(endpoint, {
        method: 'POST',
        headers: {
          'content-type': 'application/json',
        },
        body: JSON.stringify({ username: cleaned }),
      });

      if (!response.ok) {
        const payload = (await response.json().catch(() => null)) as { error?: string } | null;
        setError(sanitizeErrorMessage(payload?.error ?? API_ERROR));
        return;
      }

      setError('WebAuthn verification step pending backend implementation.');
    } catch {
      setError(API_ERROR);
    } finally {
      setSubmitting(null);
    }
  };

  return (
    <main style={{ display: 'grid', placeItems: 'center', minHeight: '100vh', padding: 24 }}>
      <section
        style={{
          width: 'min(440px, 100%)',
          padding: 24,
          borderRadius: 16,
          border: '1px solid rgba(15,118,110,0.2)',
          backgroundColor: 'rgba(255,255,255,0.88)',
          boxShadow: '0 20px 45px rgba(31,41,55,0.12)',
          backdropFilter: 'blur(4px)',
        }}
      >
        <h1 style={{ margin: '0 0 8px', fontSize: 32, lineHeight: 1.2 }}>Welcome Back</h1>
        <p style={{ margin: '0 0 20px', color: '#4b5563' }}>
          Use your passkey to register or sign in.
        </p>

        <form
          onSubmit={(event) => {
            event.preventDefault();
            void submit('login');
          }}
        >
          <label htmlFor="username" style={{ display: 'block', fontWeight: 600, marginBottom: 8 }}>
            Username
          </label>
          <input
            id="username"
            name="username"
            type="text"
            value={username}
            onChange={(event) => setUsername(event.target.value)}
            autoComplete="username"
            disabled={isBusy}
            style={{
              width: '100%',
              height: 44,
              borderRadius: 10,
              border: '1px solid #cbd5e1',
              padding: '0 12px',
              fontSize: 16,
              marginBottom: 16,
            }}
          />

          {error ? (
            <p
              role="alert"
              style={{
                margin: '0 0 12px',
                color: '#991b1b',
                backgroundColor: '#fee2e2',
                border: '1px solid #fecaca',
                padding: '10px 12px',
                borderRadius: 8,
                fontSize: 14,
              }}
            >
              {error}
            </p>
          ) : null}

          <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: 12 }}>
            <button
              type="button"
              disabled={isBusy}
              onClick={() => {
                void submit('register');
              }}
              style={{
                height: 44,
                borderRadius: 10,
                border: '1px solid #0f766e',
                background: '#ccfbf1',
                color: '#0f766e',
                fontWeight: 700,
                cursor: 'pointer',
              }}
            >
              {submitting === 'register' ? 'Registering...' : 'Register'}
            </button>
            <button
              type="submit"
              disabled={isBusy}
              style={{
                height: 44,
                borderRadius: 10,
                border: 'none',
                background: '#0f766e',
                color: 'white',
                fontWeight: 700,
                cursor: 'pointer',
              }}
            >
              {submitting === 'login' ? 'Signing In...' : 'Login'}
            </button>
          </div>
        </form>
      </section>
    </main>
  );
}
